/**
 * A tool invocation shown as one expandable row (`design/components/tool-call.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tool-call.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import * as zag from '@zag-js/collapsible'
import { normalizeProps } from '@zag-js/solid'

import {
  Icon,
  agentMember,
  claimSlot,
  classes,
  createDerived,
  elementRef,
  mergeParts,
  resolveSlot,
  scope,
  useDirection,
  useMachine,
  type Defaults,
  type IconRole,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/ai/tool-call.module.css'
import CodeBlock from '../structure/CodeBlock'
import JsonTree from '../structure/JsonTree'

export type ToolCallStatus = 'pending' | 'running' | 'done' | 'error' | 'denied' | 'approval'

export interface ToolCallMessages {
  input: string
  output: string
  status: Record<ToolCallStatus, string>
}

export interface ToolCallProps {
  defaultOpen?: boolean
  /**
   * The duration, preformatted by the app, such as "1.2s".
   */
  duration?: string
  /**
   * The tool's mark, `tool` by default, or `terminal`, `network` or `document` when the app
   * knows the kind.
   */
  icon?: IconRole
  /**
   * The arguments, rendered as JsonTree for a value or as CodeBlock for a string.
   */
  input?: unknown
  /**
   * The app's text for a failure or a refusal.
   */
  message?: string
  /**
   * All of the card's text (generic English defaults), which localized hosts replace.
   */
  messages?: ToolCallMessages
  /**
   * The tool's name as the model called it, such as `read_file` or `search_web`.
   */
  name: string
  onOpenChange?: (open: boolean) => void
  open?: boolean
  /**
   * The result, such as a CodeBlock, a JsonTree or a Markdown.
   */
  output?: JSX.Element
  status: 'error' | 'denied' | 'done' | 'pending' | 'running' | 'approval'
  /**
   * One line describing the call, such as the file read or the query run.
   */
  summary?: string
}

/** A tool invocation shown as one expandable row. */
export default function ToolCall(given: ToolCallProps): JSX.Element {
  const props = mergeProps(
    {
      icon: 'tool',
      defaultOpen: false,
      messages: (() => ({
        input: 'Input',
        output: 'Output',
        status: {
          pending: 'Pending',
          running: 'Running',
          done: 'Done',
          error: 'Failed',
          denied: 'Denied',
          approval: 'Awaiting approval',
        },
      }))(),
    } as Defaults<ToolCallProps, 'icon' | 'defaultOpen' | 'messages'>,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const trigger = elementRef<HTMLElement>()
    const outputSlot = resolveSlot(() => props.output)
    const running = createDerived(() => props.status === 'running')
    const hasBody = createDerived(
      () =>
        props.input !== undefined || Boolean(outputSlot.filled()) || props.message !== undefined,
    )
    const statusIcon = createDerived(
      () =>
        (
          ({
            pending: 'time',
            running: 'loading',
            done: 'success',
            error: 'error',
            denied: 'denied',
            approval: 'help',
          }) as const
        )[props.status],
    )
    const documentDirection = useDirection(() => trigger.value)
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          open: props.open,
          defaultOpen: props.defaultOpen,
          disabled: !hasBody.value,
          onOpenChange: (details) => {
            props.onOpenChange?.(details.open)
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'ToolCall',
        element: () => trigger.value,
        state: () => ({ status: props.status, expanded: api.value.open }),
        actions: {
          expand: () =>
            (() => {
              if (!hasBody.value) throw new Error('The call has nothing to show.')
              api.value.setOpen(true)
            })(),
          collapse: () => api.value.setOpen(false),
        },
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <div
        {...mergeParts(api.value.getRootProps(), {
          class: styles.card,
          'data-status': props.status,
          'aria-busy': running.value ? true : undefined,
          'data-member': 'tool-call',
        })}
      >
        {/* trigger */}
        <button
          {...mergeParts(api.value.getTriggerProps(), {
            class: styles.trigger,
            disabled: !hasBody.value,
          })}
          ref={trigger.attach}
        >
          <span class={styles.mark}>
            <Icon name={props.icon} size="sm" />
          </span>
          <span class={styles.name}>{props.name}</span>
          {props.summary !== undefined ? <span class={styles.summary}>{props.summary}</span> : null}
          <span class={styles.trailing}>
            {props.duration !== undefined ? (
              <span class={styles.duration}>{props.duration}</span>
            ) : null}
            <span class={classes(styles.status, running.value ? styles.spinning : undefined)}>
              <Icon name={statusIcon.value} size="sm" />
            </span>
            <span class={styles.reader}>{props.messages.status[props.status]}</span>
            {hasBody.value ? (
              <span class={styles.chevron}>
                <Icon name="down" size="sm" />
              </span>
            ) : null}
          </span>
        </button>
        {hasBody.value ? (
          <div
            {...mergeParts(api.value.getContentProps(), {
              class: styles.content,
              style: {
                '--radix-collapsible-content-height': Object(api.value.getContentProps().style)[
                  '--height'
                ],
              },
            })}
          >
            <div class={styles.inner}>
              {props.input !== undefined ? (
                <div class={styles.section}>
                  <span class={styles.heading}>{props.messages.input}</span>
                  {typeof props.input === 'string' ? (
                    <CodeBlock label={props.messages.input}>{props.input}</CodeBlock>
                  ) : (
                    <JsonTree data={props.input} label={props.messages.input} defaultDepth={1} />
                  )}
                </div>
              ) : null}
              {outputSlot.filled() ? (
                <div class={styles.section}>
                  <span class={styles.heading}>{props.messages.output}</span>
                  {outputSlot()}
                </div>
              ) : null}
              {props.message !== undefined ? <p class={styles.message}>{props.message}</p> : null}
            </div>
          </div>
        ) : null}
      </div>
    )
  })
}
